insert into part_photo_research (mpn_key, sku, mpn, verdict, reason, image_url, candidates) values
  ('BUNN324000003', 'BUNN32400.0003', '32400.0003', 'confirmed', 'Exact MPN with part-specific images on 3 independent sites (Parts Town, WebstaurantStore, TigerChef) plus Schedule73 (likely Parts Town imagery). Agreement inferred from markup (Webstaurant alt: green circuit board); pixels not inspected, so spot-check before auto-attach.', 'https://cdnimg.webstaurantstore.com/images/products/large/589744/2127263.jpg', '[{"imageUrl": "https://partstown.sirv.com/products/BU/BU32400.0003.view?thumb&image.rules=G0&w=800", "pageUrl": "https://www.partstown.com/bunn/bu32400-0003", "site": "Parts Town", "mpnShown": "Mfr Part #: 32400.0003", "watermark": false}, {"imageUrl": "https://cdnimg.webstaurantstore.com/images/products/large/589744/2127263.jpg", "pageUrl": "https://www.webstaurantstore.com/timer-kit-dgtl-240v-no-a/233324000003.html", "site": "WebstaurantStore", "mpnShown": "MFR #: 32400.0003", "watermark": false}, {"imageUrl": "https://tigerchef.b-cdn.net/itempics/TIMER-KIT--DGTL-240V-NO-ADAPTER-408712_medium.jpg", "pageUrl": "https://www.tigerchef.com/timer-kit-dgtl-240vno-adapter.html", "site": "TigerChef", "mpnShown": "MPN 32400.0003", "watermark": false}, {"imageUrl": "https://www.schedule73parts.us/cdn/shop/products/BU32400.0003.gif?v=1632558574&width=1214", "pageUrl": "https://www.schedule73parts.us/products/bu32400-0003", "site": "Schedule73Parts", "mpnShown": "MPN: 32400.0003", "watermark": false}]'::jsonb),
  ('BUNN111740001', 'BUNN11174.0001', '11174.0001', 'review', 'No listing of exact MPN 11174.0001 found on any site; only sibling 11174.0002 is listed (different MPN, does not count). Restaurant Parts Direct names 11174.0001 under a ''Replacement'' heading on the 11174.0002 page without explaining the relationship.', null, '[]'::jsonb),
  ('BUNN371920000', 'BUNN37192.0000', '37192.0000', 'review', 'Only 2 sources show the exact MPN with an image (Parts Town, HowdyBrewer); fewer than 3.', null, '[{"imageUrl": "https://partstown.sirv.com/products/BU/BU37192.0000.view?thumb&image.rules=G0&w=800", "pageUrl": "https://www.partstown.com/bunn/bu37192-0000", "site": "Parts Town", "mpnShown": "Mfr Part #: 37192.0000", "watermark": false}, {"imageUrl": "https://www.howdybrewer.com/cdn/shop/files/37192.0000.jpg?v=1765901601&width=800", "pageUrl": "https://www.howdybrewer.com/products/normal-prg-rinse-imix-decal", "site": "HowdyBrewer", "mpnShown": "BUNN 37192.0000 Normal PRG Rinse IMIX Decal", "watermark": false}]'::jsonb),
  ('FETCO10240002000', 'FETCO1024.00020.00', '1024.00020.00', 'confirmed', 'Exact MPN with part-specific images on 3 independent sites (Parts Town, Espresso Parts, WebstaurantStore); alt texts agree (dark gray / black rubber gasket). Parts Town notes previous part # FE24012. Pixels not inspected, so spot-check before auto-attach.', 'https://partstown.sirv.com/products/FE/FE1024.00020.00/fe10240002000.jpg?scale.option=fill&w=700&h=0', '[{"imageUrl": "https://partstown.sirv.com/products/FE/FE1024.00020.00/fe10240002000.jpg?scale.option=fill&w=700&h=0", "pageUrl": "https://www.partstown.com/fetco/fe1024-00020-00", "site": "Parts Town", "mpnShown": "Mfr Part #: 1024.00020.00", "watermark": false}, {"imageUrl": "https://www.espressoparts.com/cdn/shop/products/FET_21024_800x.jpg?v=1783616751", "pageUrl": "https://www.espressoparts.com/products/fetco-s-53-fill-valve-gasket", "site": "Espresso Parts", "mpnShown": "Fetco part #: 1024.00020.00 (SKU FET_21024)", "watermark": false}, {"imageUrl": "https://cdnimg.webstaurantstore.com/images/products/large/242030/1183651.jpg", "pageUrl": "https://www.webstaurantstore.com/fetco-1024-00020-00-gasket-fill-vlv/HP1024000200.html", "site": "WebstaurantStore", "mpnShown": "Fetco 1024.00020.00 Gasket, Fill Vlv", "watermark": false}]'::jsonb),
  ('BUNN015320000', 'BUNN01532.0000', '01532.0000', 'review', 'Only Parts Town and Schedule73 (likely Parts Town imagery) list the exact MPN; fewer than 3 independent sources. TigerChef''s similar washer is 01532.0005 (does not count).', null, '[{"imageUrl": "https://partstown.sirv.com/products/BU/BU01532.0000.view?thumb&image.rules=G0&w=200", "pageUrl": "https://www.partstown.com/bunn/bu01532-0000", "site": "Parts Town", "mpnShown": "Mfr Part #: 01532.0000", "watermark": false}, {"imageUrl": "https://www.schedule73parts.us/cdn/shop/products/BU01532.0000.gif?v=1632938890&width=1214", "pageUrl": "https://www.schedule73parts.us/products/bu01532-0000", "site": "Schedule73Parts", "mpnShown": "MPN: 01532.0000", "watermark": false}]'::jsonb),
  ('BUNN027660000', 'BUNN02766.0000', '02766.0000', 'review', '3 sites list the exact MPN (HowdyBrewer, Ekuep, ShopAtStop) but the evidence is weak: ShopAtStop''s image is a screenshot file (may contain another site''s UI or watermark) and its title (STS35) conflicts with its listed models; HowdyBrewer pricing is inconsistent; no major distributor (Parts Town or WebstaurantStore) listing found. Agreement cannot be established.', null, '[{"imageUrl": "https://www.howdybrewer.com/cdn/shop/files/02766_0000.jpg?v=1765901607&width=800", "pageUrl": "https://www.howdybrewer.com/products/faucet-seat-cup-silicone", "site": "HowdyBrewer", "mpnShown": "BUNN 02766.0000 Faucet Seat Cup Silicone", "watermark": false}, {"imageUrl": "https://cdn.ekuep.com/v4ekuep/img/p/5/5/1/1/0/55110-large_default.jpg", "pageUrl": "https://www.ekuep.com/en/bunn-o-matic-02766-0000-faucet-seat-cup", "site": "Ekuep", "mpnShown": "Reference: 02766.0000", "watermark": false}]'::jsonb),
  ('FETCO52018', 'FETCO52018', '52018', 'review', 'Only Parts Town and Schedule73 list the exact MPN (fewer than 3 independent sources), and Schedule73 carries two different image files. Parts Town shows it In Stock (22 available), which conflicts with the Katz ''discontinued'' label.', null, '[{"imageUrl": "https://partstown.sirv.com/products/FE/FE52018.view?thumb&image.rules=G0&w=800", "pageUrl": "https://www.partstown.com/fetco/fe52018", "site": "Parts Town", "mpnShown": "Mfr Part #: 52018", "watermark": false}, {"imageUrl": "https://www.schedule73parts.us/cdn/shop/products/pdp_FETCO_RELAY_MERCURY_35_AMP_2_POLE-FE52018.jpg?v=1603151571&width=1214", "pageUrl": "https://schedule73parts.us/products/fe52018", "site": "Schedule73Parts", "mpnShown": "MPN: 52018", "watermark": false}]'::jsonb),
  ('BUNN533440001', 'BUNN53344.0001', '53344.0001', 'review', 'Only Parts Town has an image; Restaurant Parts Direct lists the exact MPN with no image. Fewer than 3 sources with a photo.', null, '[{"imageUrl": "https://partstown.sirv.com/products/BU/BU53344.0001.view?thumb&image.rules=G0&w=800", "pageUrl": "https://www.partstown.com/bunn/bu53344-0001", "site": "Parts Town", "mpnShown": "Mfr Part #: 53344.0001", "watermark": false}]'::jsonb),
  ('BUNN055150000', 'BUNN05515.0000', '05515.0000', 'review', '3 sites show the exact MPN with images, but Schedule73 likely reuses Parts Town imagery (only 2 independent), and the descriptions conflict: WebstaurantStore''s alt text says ''clear plastic'' while RestaurantSupply''s title says ''White Silicone''.', null, '[{"imageUrl": "https://partstown.sirv.com/products/BU/BU05515.0000/bu055150000.jpg?scale.option=fill&w=700&h=0", "pageUrl": "https://www.partstown.com/bunn/bu05515-0000", "site": "Parts Town", "mpnShown": "Mfr Part #: 05515.0000", "watermark": false}, {"imageUrl": "https://cdnimg.webstaurantstore.com/images/products/large/517803/2160206.jpg", "pageUrl": "https://www.webstaurantstore.com/gasket-sprayhead-tube/233055150000.html", "site": "WebstaurantStore", "mpnShown": "MFR #: 05515.0000", "watermark": false}, {"imageUrl": "https://www.schedule73parts.us/cdn/shop/products/BU05515.0000.jpg?v=1632555452&width=1214", "pageUrl": "https://schedule73parts.us/products/bu05515-0000", "site": "Schedule73Parts", "mpnShown": "MPN: 05515.0000", "watermark": false}]'::jsonb),
  ('BUNN363640000', 'BUNN36364.0000', '36364.0000', 'review', 'Only 2 sources (Parts Town, WebstaurantStore) show the exact MPN with an image; fewer than 3.', null, '[{"imageUrl": "https://partstown.sirv.com/products/BU/BU36364.0000.view?thumb&image.rules=G0&w=800", "pageUrl": "https://www.partstown.com/bunn/bu36364-0000", "site": "Parts Town", "mpnShown": "Mfr Part #: 36364.0000", "watermark": false}, {"imageUrl": "https://cdnimg.webstaurantstore.com/images/products/large/807262/2727756.jpg", "pageUrl": "https://www.webstaurantstore.com/bunn-36364-0000-gasket-control-panel-bezel/233363640000.html", "site": "WebstaurantStore", "mpnShown": "Bunn 36364.0000 Gasket, Control Panel Bezel", "watermark": false}]'::jsonb),
  ('LMF103401', 'LMF.1.034.01', 'F.1.034.01', 'review', '3 listings found (Parts Town, Black Rabbit, Espresso Parts), but each gives F.1.034 as the main MPN. F.1.034.01 appears only in brackets in the Parts Town and Black Rabbit titles, and Espresso Parts says only ''replaces part #F.1.034'', which points to a revision/supersession rather than an exact match. Espresso Parts'' two image alt texts disagree (faceted vs hexagonal). Images not checked by eye, so agreement is unverified, and Black Rabbit''s independence is uncertain.', null, '[{"imageUrl": "https://partstown.sirv.com/products/LAM/LAMF.1.034.view", "pageUrl": "https://www.partstown.com/la-marzocco/lamf-1-034", "site": "Parts Town", "mpnShown": "F.1.034 (title: ''F.1.034 LINEA PB, STEAM VALVE KNOB (F.1.034.01)'')", "watermark": null}, {"imageUrl": "https://blackrabbitservice.com/cdn/shop/files/f1034-la-marzocco-linea-pb-steam-valve-knob-f103401-924094.png?v=1713291176&width=1214", "pageUrl": "https://blackrabbitservice.com/products/f-1-034-lm-linea-pb-steam-valve-knob-f-1-034-01", "site": "Black Rabbit Service Co.", "mpnShown": "F.1.034 (title: ''F.1.034 ... (F.1.034.01)'')", "watermark": null}, {"imageUrl": "https://www.espressoparts.com/cdn/shop/products/MZ3401.png?v=1785168689", "pageUrl": "https://www.espressoparts.com/products/la-marzocco-linea-pb-steam-valve-knob", "site": "Espresso Parts", "mpnShown": "F.1.034 (''replaces part #F.1.034''; SKU MZ_F1034; F.1.034.01 not shown)", "watermark": null}]'::jsonb),
  ('EVER101231', 'EVER101231', '101231', 'review', 'No source found listing Eversys 101231 (searched Black Rabbit, Service Sphere, Parts Town and the open web).', null, '[]'::jsonb),
  ('M28254', 'M28254', 'M28254', 'review', 'Only 1 source (Black Rabbit). Its title says ''Shear Pins'' but the description says ''3X3X30 Key'', so the name is inconsistent. Image not checked by eye.', null, '[{"imageUrl": "https://blackrabbitservice.com/cdn/shop/files/m28254-la-marzocco-mazzer-shear-pins-448160.png?v=1713291757&width=1214", "pageUrl": "https://blackrabbitservice.com/collections/spare-parts/products/m28254-lm-mazzer-3x3x30-key", "site": "Black Rabbit Service Co.", "mpnShown": "M28254", "watermark": null}]'::jsonb),
  ('LME10153', 'LME.1.015.3', 'E.1.015.3', 'review', 'Only 1 source (Parts Town). Black Rabbit, Espresso Parts and Coffee Parts AU carry only neighbouring numbers (E.1.015.1, .2, .4, .5, /6), which do not count.', null, '[{"imageUrl": "https://partstown.sirv.com/products/LAM/LAME.1.015.3.view", "pageUrl": "https://www.partstown.com/la-marzocco/lame-1-015-3", "site": "Parts Town", "mpnShown": "E.1.015.3", "watermark": null}]'::jsonb),
  ('EVER108027', 'EVER108027', '108027', 'review', 'No source found listing Eversys 108027 (searched Black Rabbit, Service Sphere, Parts Town and the open web).', null, '[]'::jsonb),
  ('EVER100703', 'EVER100703', '100703', 'review', 'No source found listing Eversys 100703 (searched Black Rabbit, Service Sphere, Parts Town and the open web).', null, '[]'::jsonb),
  ('EVER102613', 'EVER102613', '102613', 'review', 'No source found listing Eversys 102613. A La Marzocco VITE3X8 M3x8 pan-head screw exists at Parts Town, but it is a different part and does not count.', null, '[]'::jsonb),
  ('LMA7013', 'LMA.7.013', 'A.7.013', 'review', 'Only 1 source (Parts Town). Generic 6mm x G1/8 elbows found elsewhere are not this MPN.', null, '[{"imageUrl": "https://partstown.sirv.com/products/LAM/LAMA.7.013.view", "pageUrl": "https://www.partstown.com/la-marzocco/lama-7-013", "site": "Parts Town", "mpnShown": "A.7.013", "watermark": null}]'::jsonb),
  ('LMA5013', 'LMA.5.013', 'A.5.013', 'review', 'Only 1 source (Espresso Parts), and it calls A.5.013 a ''Removable Portafilter Spout - Single'' (Strada-style push-fit), which conflicts with Katz''s ''Fixed Single Spout''. A.5.113 and A.5.024 are look-alike numbers and do not count.', null, '[{"imageUrl": "https://www.espressoparts.com/cdn/shop/products/mz_a5013.jpg?v=1783620884", "pageUrl": "https://www.espressoparts.com/parts/commercial-espresso-machine-parts/la-marzocco/la-marzocco-strada-mp/strada-mp-portafilter-assembly/la-marzocco-removable-portafilter-spout-single", "site": "Espresso Parts", "mpnShown": "A.5.013", "watermark": null}]'::jsonb),
  ('EVER101923', 'EVER101923', '101923', 'review', 'No source found listing Eversys 101923 (searched Black Rabbit, Service Sphere, Parts Town and the open web).', null, '[]'::jsonb),
  ('FA903722030', 'FA903722030', '903722030', 'review', 'No source found showing MPN 903722030 (or 903-722-030). Coffee Parts AU level sight glass kit 630685 lists no OEM number and uses a placeholder image.', null, '[]'::jsonb),
  ('FA429959000', 'FA429959000', '429959000', 'review', 'Only 2 sources show the exact MPN; only one (eBay, ''for 429959000'', possibly aftermarket) has a real photo. Ambrogio shows a store logo/no-image placeholder.', null, '[{"imageUrl": "https://i.ebayimg.com/images/g/KaYAAOSwQy5lZidc/s-l1600.png", "pageUrl": "https://www.ebay.com/itm/155915601244", "site": "eBay (seller micsurplus)", "mpnShown": "429959000 / 429-959-000", "watermark": false}]'::jsonb),
  ('RAN10701259', 'RAN10701259', '10701259', 'review', 'No source found listing MPN 10701259. Parts Town Rancilio panels list only right side panel 00028955 (different MPN); search hits were Epoca panels (different parts).', null, '[]'::jsonb),
  ('FA402215000', 'FA402215000', '402215000', 'review', 'No source found listing MPN 402215000. Espresso Parts F_146 steam/water valve gasket does not list it.', null, '[]'::jsonb),
  ('FA4701024555', 'FA4701024555', '4701024555', 'review', 'Only one source (Espresso Parts F_201) lists 4701024555, and only as a cross-reference on a universal 3/8in copper gasket; fewer than 3 sources.', null, '[{"imageUrl": "https://www.espressoparts.com/cdn/shop/products/f_201_1_5de11841-11a2-4f68-a769-8458232df3f5_1024x.jpg?v=1610086815", "pageUrl": "https://www.espressoparts.com/products/3-8-copper-gasket", "site": "Espresso Parts", "mpnShown": "Replaces: Cimbali/Faema 4701024555 (SKU F_201)", "watermark": false}]'::jsonb),
  ('FA539000101', 'FA539000101', '539000101', 'review', 'No source found listing MPN 539000101.', null, '[]'::jsonb),
  ('FA402221000F', 'FA402221000F', '402221000', 'review', 'No source found listing MPN 402221000 (trailing F treated as Katz suffix).', null, '[]'::jsonb),
  ('NS98030501', 'NS98030501', '98030501', 'review', 'Only one source (Parts Town NUOV98030501, ''Tube, Inner Coffee Tank, PTFE'') shows the exact MPN with an apparent real photo; fewer than 3 sources.', null, '[{"imageUrl": "https://partstown.sirv.com/products/NUOV/NUOV98030501.view?thumb&image.rules=G0&w=800", "pageUrl": "https://www.partstown.com/p/nuova-simonelli-usa/nuov98030501", "site": "Parts Town", "mpnShown": "Mfr Part #: 98030501 (Parts Town # NUOV98030501)", "watermark": false}]'::jsonb),
  ('FA401400000', 'FA401400000', '401400000', 'review', 'No source found listing MPN 401400000.', null, '[]'::jsonb),
  ('FA537068400', 'FA537068400', '537068400', 'review', 'No source found listing current MPN 537068400. Coffee Parts 591549 lists only superseded 537060600 and 958889000 (Katz shows 95888900, likely truncated), with a placeholder image; supersessions do not count.', null, '[]'::jsonb),
  ('BWT812191', 'BWT812191', '812191', 'review', 'No source shows MPN 812191. Two listings match the name only: Whole Latte Love (SKU 23515, no MPN) and ChefSupplies.ca (Faema no. B09-81291). A near-identical 3/8 x 1/4 sibling exists, so a name match is not safe.', null, '[{"imageUrl": "https://www.wholelattelove.com/cdn/shop/products/bwt_reduction_fitting_img_9537.jpg?v=1536331955&width=1946", "pageUrl": "https://wholelattelove.com/products/reduction-fm-3-8-x-o-3-8-adapter", "site": "Whole Latte Love", "mpnShown": "SKU 23515 (no BWT MPN shown)", "watermark": false}, {"imageUrl": "https://www.chefsupplies.ca/cdn/shop/files/Faema-BWT-Reduction-FM-38-x-38-Adapter-B09-81291.webp?v=1782799594", "pageUrl": "https://www.chefsupplies.ca/products/faema-bwt-reduction-fm-3-8-x-3-8-adapter-b09-81291", "site": "ChefSupplies.ca", "mpnShown": "B09-81291 (Faema number)", "watermark": false}]'::jsonb),
  ('MAHL302365', 'MAHL302365', '302365', 'review', 'No source lists 302365. Ekuep shows a different number (302375) on an on/off switch. Parts Town could not be fetched.', null, '[]'::jsonb),
  ('WF30005802', 'WF300-05802', '300-05802', 'review', 'No source lists WF300-05802. Base number 300-05802 is a Pentair Everpure S5-Q (17.5 in overall, 5 micron), not OptiPure. Pentair''s spec sheet has a diagram only. Restaurant Parts Direct listings (one marked ''Compatible'') showed no image. Fewer than 3 photo sources.', null, '[]'::jsonb),
  ('DIT40198', 'DIT40198', '240198 (Katz 40198)', 'review', 'Only one source (Prima, MPN 240198, ''Updated Magnet with holder and magnet screw''), and its image is the Ditting logo, not the part. The 40198-to-240198 mapping is inferred.', null, '[]'::jsonb),
  ('DIT55707', 'DIT55707', '55707 / 255707', 'review', 'No source lists 55707 or 255707. The closest Prima item (703038 Rubber Buffer, 804) is a different MPN.', null, '[]'::jsonb),
  ('GMC6', 'GMC6', 'GMC6', 'review', 'No source lists GMC6. It appears to be a distributor code, not a John Guest MPN (John Guest uses PI0112xxS / PP0112xxW). The exact John Guest part (tube and thread size) needs confirming with Holiday House.', null, '[]'::jsonb),
  ('DIT40264', 'DIT40264', '40264 / 240264', 'review', 'No source lists 40264 or 240264. The closest Prima item (703450 KR804 Eccentric set) is a different MPN.', null, '[]'::jsonb),
  ('MAHL257013', 'MAHL257013', '257013', 'review', 'No source lists 257013. The nearest contactor listing (EK43/Guatemala) is MPN 703570, a different part.', null, '[]'::jsonb),
  ('DIT40078', 'DIT40078', '240078 (Katz 40078)', 'review', 'Only one source (Prima, MPN 240078), and its image is the Ditting logo. Prima says the part is no longer sold individually and to buy 703425 (Fixing Cap Set - Silver) to get the spring, so it is effectively superseded.', null, '[]'::jsonb),
  ('MAHL309560', 'MAHL309560', '309560', 'review', '309560 is superseded by 702926. Only Prima (photo seen) and Ekuep (no image seen) show 309560 as the current MPN; Espresso Parts, Black Rabbit and ProCoffeeGear list it only as the old number for 702926. Fewer than 3 exact-MPN photo sources. Best candidate for human approval is Prima''s ''-wbg'' product shot.', null, '[{"imageUrl": "https://cdn11.bigcommerce.com/s-6h7ychjk4/images/stencil/1280x1280/products/7700/87537/mahlkonig-standard-hopper-wbg__25208.1620751909.jpg?c=1&imbypass=on", "pageUrl": "https://prima-coffee.com/parts/mahlkonig/309560-mahlk-sp", "site": "Prima Coffee", "mpnShown": "309560", "watermark": false}]'::jsonb)
