-- Parts from the NetSuite item export: Class as the file has it, Get Later (a mark to pull the part later; it does
-- not change price or stock), and each part's photo status.
alter table billing_items add column if not exists item_class text;
alter table billing_items add column if not exists get_later boolean not null default false;
alter table billing_items add column if not exists get_later_at timestamptz;
alter table billing_items add column if not exists get_later_by text;
-- 'confirmed': the attached photo was confirmed (same MPN on 3+ sources that agree, or chosen by a person).
alter table billing_items add column if not exists photo_status text;
alter table billing_items add column if not exists photo_source_url text;
alter table billing_items add column if not exists photo_confirmed_by text;
alter table billing_items add column if not exists photo_confirmed_at timestamptz;

create index if not exists billing_items_get_later_idx on billing_items (get_later) where get_later;

-- Photo research by part number. verdict 'confirmed' = the same MPN with a matching photo on 3+ independent sources;
-- 'review' = not confirmed: flag Confirm Photo and show the candidates for a person to choose from (or none).
-- Keyed by the part number with case, spaces and punctuation removed, so it meets the part however it was loaded.
create table if not exists part_photo_research (
  mpn_key       text primary key,
  sku           text not null,
  mpn           text,
  verdict       text not null check (verdict in ('confirmed', 'review')),
  reason        text,
  image_url     text,
  candidates    jsonb not null default '[]'::jsonb,
  researched_at timestamptz not null default now()
);

-- Pilot batch: 40 part numbers researched Oct 13-14, 2026 (see reports/NetSuite part photo sourcing.md).
on conflict (mpn_key) do nothing;
